    // 3. Register nodes
    graph.registerNode(sensor1);
    graph.registerNode(sensor2);
    graph.registerNode(actuator);

    // 4. Set up initial dependency (sensor1 -> actuator)
    graph.addDependency(sensor1, actuator);

    // 5. Save node state for rollback
