#pragma once

#include <reaction/concurrency/thread_manager.h>
#include <thread>

namespace test_reaction {

struct ThreadSafetyStatus {
    bool safetyBefore;
    bool safetyAfter;
    std::size_t threadCountBefore;
    std::size_t threadCountAfter;
};

inline ThreadSafetyStatus test_thread_manager_multithread() {
    // 1. Get thread manager instance
    auto& manager = reaction::ThreadManager::getInstance();

    // 2. Reset thread manager state
    manager.resetForTesting();

    // 3. Register current thread
    REACTION_REGISTER_THREAD;

    // 4. Get thread count and safety status before
    std::size_t threadCountBefore = manager.getThreadCount();
    bool safetyBefore = manager.isThreadSafetyEnabled();

    // 5. Create and start worker thread
    std::thread worker([&manager]() {
        // Register worker thread
        REACTION_REGISTER_THREAD;

        // Perform some work
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    });

    // 6. Wait for worker thread
    worker.join();

    // 7. Get thread count and safety status after
    std::size_t threadCountAfter = manager.getThreadCount();
    bool safetyAfter = manager.isThreadSafetyEnabled();

    // 8. Return thread safety status
    return {safetyBefore, safetyAfter, threadCountBefore, threadCountAfter};
}

}  // namespace test_reaction
