    graph.collectObservers(node1, observers);

    // 8. Get cache statistics before cleanup
    auto statsBefore = graph.getCacheStats();
    size_t entriesBefore = statsBefore.entries;

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    auto statsAfter = graph.getCacheStats();
    size_t entriesAfter = statsAfter.entries;
    double hitRatio = statsAfter.hitRatio;

    // 11. Close all nodes
    node1->close();
    node2->close();
    node3->close();

