    // Step 1: Get thread manager instance
    auto& manager = reaction::ThreadManager::getInstance();

    // Step 2: Reset thread manager state
    manager.resetForTesting();

    // Step 3: Get thread safety status before guard
    bool safetyBeforeGuard = manager.isThreadSafetyEnabled();

    // Step 4: Get thread count before guard
    std::size_t threadCountBeforeGuard = manager.getThreadCount();

    // Step 5: Create a worker thread with ThreadRegistrationGuard
    std::thread worker([&manager]() {
        reaction::ThreadRegistrationGuard guard;
        // Perform some work to ensure the thread is registered
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    });

    // Step 6: Wait for worker thread to complete
    worker.join();

    // Step 7: Get thread safety status after guard
    bool safetyAfterGuard = manager.isThreadSafetyEnabled();

    // Step 8: Get thread count after guard
    std::size_t threadCountAfterGuard = manager.getThreadCount();

    // Step 9: Return thread guard state
    return ThreadGuardState{
        safetyBeforeGuard,
        safetyAfterGuard,
        threadCountBeforeGuard,
        threadCountAfterGuard
    };
}

