#pragma once

#include <array>
#include <cstddef>
#include <reaction/memory/sbo_resource.h>

namespace test_reaction {

struct SmallPayload {
    int value;
    bool operator!=(const SmallPayload& other) const = default;
};

struct LargePayload {
    std::array<int, 64> data{};
    bool operator!=(const LargePayload& other) const = default;
};

struct SboStorageStatus {
    bool updateReportedChange;
    bool smallUsingSBO;
    std::size_t smallStackUsage;
    bool largeInitialized;
    bool largeUsingSBO;
};

inline SboStorageStatus test_sbo_storage_info(int initialSmall,
                                       int updatedSmall,
                                       int largeSeed) {
    // 1. Create a lambda function to make large payload
    auto makeLargePayload = [largeSeed]() {
        LargePayload payload;
        for (std::size_t i = 0; i < payload.data.size(); ++i) {
            payload.data[i] = largeSeed + static_cast<int>(i);
        }
        return payload;
    };

    // 2. Create small SBOResource
    auto smallResource = reaction::memory::SBOResource<SmallPayload>({initialSmall});

    // 3. Create large SBOResource
    auto largeResource = reaction::memory::SBOResource<LargePayload>(makeLargePayload());

    // 4. Update small resource value
    bool changed = smallResource.setValue(SmallPayload{updatedSmall});

    // 5. Get storage information for small resource
    auto smallInfo = smallResource.getStorageInfo();

    // 6. Get storage information for large resource
    auto largeInfo = largeResource.getStorageInfo();

    // 7. Return SBO storage status
    return SboStorageStatus{
        changed,
        smallInfo.using_sbo,
        smallInfo.stack_usage,
        largeInfo.initialized,
        largeInfo.using_sbo
    };
}

}  // namespace test_reaction
